.darma-loader-anchor-swing {
  position: relative;
  width: 44px;
  height: 52px;
  transform-origin: top center;
  animation: darma-loader-anchor-swing-swing 1.6s ease-in-out infinite;
}
.darma-loader-anchor-swing::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 12px;
  height: 12px;
  margin-left: -6px;
  border: 3px solid var(--loader-color, #6366f1);
  border-radius: 50%;
  box-sizing: border-box;
}
.darma-loader-anchor-swing i {
  position: absolute;
  top: 12px;
  left: 50%;
  width: 4px;
  height: 30px;
  margin-left: -2px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
}
.darma-loader-anchor-swing i::before {
  content: "";
  position: absolute;
  top: 4px;
  left: -9px;
  width: 22px;
  height: 4px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
}
.darma-loader-anchor-swing i::after {
  content: "";
  position: absolute;
  bottom: -2px;
  left: -13px;
  width: 30px;
  height: 16px;
  border: 4px solid var(--loader-color, #6366f1);
  border-top: 0;
  border-radius: 0 0 50% 50%;
  box-sizing: border-box;
}
@keyframes darma-loader-anchor-swing-swing {
  0%, 100% { transform: rotate(-14deg); }
  50% { transform: rotate(14deg); }
}

